BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十六", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/32533eed18a7fca71281bc84f91c0f9a586b003c/content/books/zizhi-tongjian/vol-293/year-0956/part-03/sources/library/jiuwudaishi-116-april-yangzhou-liuhe/source.txt", "note": "《旧五代史》卷一百十六，段落 jiu-wudaishi-205deb4a7860-p002755；EPUB电子本，纸本及异文待核", "id": "3b9dc74a-ebf9-5ac4-826b-516718d20629"}, {"title": "宋史·巻一", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/32533eed18a7fca71281bc84f91c0f9a586b003c/content/books/zizhi-tongjian/vol-293/year-0956/part-03/sources/library/songshi-1-liuhe-battle-956/source.txt", "note": "《宋史》巻一，段落 songshi-9c6e46fee832-p000514；EPUB电子本，纸本及异文待核", "id": "4039a891-99aa-5851-bcbb-3555c7af8922"}, {"title": "资治通鉴·后周纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/32533eed18a7fca71281bc84f91c0f9a586b003c/content/books/zizhi-tongjian/vol-293/year-0956/part-03/sources/library/tongjian-293-956-april-yangzhou-liuhe/source.txt", "note": "《资治通鉴》后周纪四，段落 zizhi-tongjian-a63549944a71-p003477；电子底本待考，分段待核", "id": "7347b9e9-a086-5c4d-9248-c37e6dbe7b0b"}, {"title": "资治通鉴·后周纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d5d9d3447be330d5f5331703b94bb9b504dea8b6/content/books/zizhi-tongjian/vol-293/year-0956/part-02/sources/library/tongjian-293-956-li-deming-changzhou/source.txt", "note": "《资治通鉴》后周纪四，段落 zizhi-tongjian-a63549944a71-p003476；电子底本待考，分段待核", "id": "51d79b3a-2b70-5518-b7e9-6bdf24603483"}, {"title": "新五代史·卷六十二", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/6ff82fc5c6ceef78ebad27a4ff3e3aceb8c67445/content/books/zizhi-tongjian/vol-286/year-0947/part-06/sources/library/xinwudaishi-062-947-succession/source.txt", "note": "《新五代史》卷六十二，段落 xin-wudaishi-b08f244b9241-p003143；EPUB电子本，纸本及异文待核", "id": "5d35eb07-c2a4-519c-ad22-f19ca9a01118"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "李廷珪", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀将领。947年十二月任奉銮肃卫都虞候，率二万兵出子午谷援长安。生卒年尚未录入。", "biography": null, "status": "draft", "id": "376820ae-41ca-57e0-b117-00976a8545fc"}, {"name": "吕彦琦", "aliases": ["呂彥琦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀武定节度使。956年三月孟昶整编卫圣、匡圣步骑为左右十军时，任命吕彦琦等为军使，李廷珪统领。与已录李彦琦、张彦琦姓氏不同，不直接合并。生卒年未载。", "biography": null, "status": "draft", "id": "401bad88-7755-55a2-924d-9836a9df1135"}, {"name": "柴克宏", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐龙武都虞候，柴再用之子。956年请求出战，其母亦上表荐子，李璟任其为右武卫将军赴常州救援。虽然装备劣、被召还，仍进军，在常州击败吴越军。生卒年待后续段落。", "biography": null, "status": "draft", "id": "e35c0e24-ccd9-5b3b-8e02-7e842ac1aeb8"}, {"name": "路彦铢", "aliases": ["路彥銖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越上直都指挥使。956年二月癸巳奉钱弘俶命进攻南唐宣州。生卒年未载。", "biography": null, "status": "draft", "id": "3af8f6aa-3cc5-5dc1-ad7c-665a3e802e03"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "白重赞", "aliases": ["白重贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周武成节度使。953年九月己亥奏报已堵塞决口的黄河。生卒年未载。", "biography": null, "status": "draft", "id": "b6889cb5-a3c4-5b6a-aa6e-7feda1afc895"}, {"name": "王晏", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐州人，947年二月任奉国都头，与赵晖、侯章谋划杀死契丹将刘愿，率数名壮士夜入府署、取库中兵器。生卒年暂未录入。", "biography": null, "status": "draft", "id": "030a26f1-62e3-5876-92b4-923b763723f0"}, {"name": "徐景达", "aliases": ["景达", "徐景達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐诰的儿子。937年十一月被封为寿阳公，姓名在本站统一使用此时的徐氏形式。具体生卒年份此段未载。", "biography": null, "status": "draft", "id": "75c1ce40-b9c2-5bfe-bdca-c73be3b25efd"}, {"name": "陈觉", "aliases": ["陳覺"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：陈觉，海陵人、参与谈议者。", "biography": null, "status": "draft", "id": "8f8c34eb-c238-596f-a688-8b8332b405a1"}, {"name": "边镐", "aliases": ["邊鎬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "金陵人，南唐通事舍人。943年十月任讨张遇贤军监军，用白昌裕为谋主，接连获胜；白昌裕建议开道绕到营后袭击，张遇贤随后逃走被捕。生卒年尚未核。", "biography": null, "status": "draft", "id": "8bcc0004-3382-5f6c-af6e-73ccf4cdd725"}, {"name": "韩熙载", "aliases": ["韓熙載", "熙载"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：韩熙载，韩叔嗣之子、拟奔吴者。", "biography": null, "status": "draft", "id": "83af8c00-ec9d-5693-9e26-56dc1a5a6a88"}, {"name": "潘承祐", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "镇武军节度判官，晋江人。王延羲与王延政交战时，多次劝王延政停战修好；王延政向闽王使者展示军队、言语傲慢时，潘承祐长跪劝谏，受到威胁仍继续进谏。具体年月及生卒年未载。", "biography": null, "status": "draft", "id": "709be4ea-d9bd-5e7a-b136-9452103cf994"}, {"name": "许文稹", "aliases": ["許文稹", "许文缜", "許文縝"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "同安人，汀州刺史。944年朱文进掌权后率郡投降朱文进。《新五代史》对应汀州守将作許文縝，保留姓名字形异文；该书后文投降王延政为另一阶段，不混为当前投降对象。生卒年未载。", "biography": null, "status": "draft", "id": "6717f767-1ab2-52b8-8015-c778cc06ee45"}, {"name": "陈德诚", "aliases": ["陳德誠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "静江指挥使。956年南唐潘承祐在泉建募兵时举荐，随后陆孟俊恢复泰州，派其戍守。生卒年未载。", "biography": null, "status": "draft", "id": "5c0f3a0f-e33c-5bb5-bed7-26075de15f3b"}, {"name": "郑彦华", "aliases": ["鄭彥華"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "建州人。956年潘承祐荐其骁勇，李璟任为将，参与南唐应对后周的军务。生卒年未载。", "biography": null, "status": "draft", "id": "2727ea31-93a8-5472-8a3d-5b3d1fa543fe"}, {"name": "林仁肇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "建州人，林仁翰的弟弟。956年由潘承祐荐任南唐将领。生卒年及后续军务待按编年续录。", "biography": null, "status": "draft", "id": "2cf3602b-35b9-55d1-b352-323aa860d16a"}, {"name": "林仁翰", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "福州南廊承旨。944年闰十二月丁酉率部反对连重遇与朱文进，杀连重遇后号召众人杀朱文进。《新五代史》称他为裨将。生卒年本段未载。", "biography": null, "status": "draft", "id": "b422146c-60a6-5f7b-ba8e-b77da41f898d"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "李重进", "aliases": ["李重進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "沧州人，福庆长公主之子，郭威的外甥，生于太原。郭威在藩镇时期的将佐，952年任恩州团练使，逐渐受重用。《宋史》还记当年内殿职务变化，具体任日未载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9769d0fb-1d80-593e-9aa3-e4c22416f835"}, {"name": "武行德", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "并州榆次人。947年受契丹命运送晋朝铠甲兵器，途中与军士夺取兵器、杀契丹监军，继而占据河阳。生卒年尚未录入。", "biography": null, "status": "draft", "id": "e0ed92f8-edb4-574b-83af-85088429a093"}, {"name": "陆孟俊", "aliases": ["陸孟俊", "陆孟俊（南唐袁州刺史）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国牙内侍卫指挥使。951年与徐威等设寨防备朗州军，并参与囚禁马希萼、拥立马希崇的政变。生卒年未载。", "biography": null, "status": "draft", "id": "9cdd0a9c-6c68-563a-a248-ebe4bdf18320"}, {"name": "韩令坤", "aliases": ["韓令坤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "磁州武安人，后周侍卫马军都指挥使。955年十一月，奉柴荣命与其他十一名将领随李谷、王彦超出征南唐。生卒年未载。", "biography": null, "status": "draft", "id": "808ffe02-5578-55cc-8c1f-2b9823cfd253"}, {"name": "张永德", "aliases": ["張永德"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "阳曲人，郭威的女婿。950年任供奉官押班，奉命给昭义节度使常思送生日礼物；常思接到杀他的密诏后拘留观望，郭威取京师后释放并道歉。生卒年本批未录。", "biography": null, "status": "draft", "id": "c1584e5c-2a3c-5c28-bbe4-7c8a05161c51"}, {"name": "赵匡胤", "aliases": ["趙匡胤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周宿卫将领，后来成为宋太祖。954年高平之战右军溃逃后，与张永德分率两翼反击北汉军。《宋史》本纪印证其率同列冲锋的记载。生卒年留待相应史料补录。", "biography": null, "status": "draft", "id": "ce0fe2a6-d446-50c7-b968-4245fd9693ad"}, {"name": "杨昭恽", "aliases": ["楊昭惲"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "曾任舒州刺史。《通鉴》追述951年陆孟俊参与废马希萼、立马希崇时，灭其家族并取财。与已有杨昭遂、杨昭俭名字不同，未因相似字形合并。生卒年未载。", "biography": null, "status": "draft", "id": "cc95565d-bafe-535a-9b03-c712f830ad7f"}, {"name": "杨氏（杨昭恽族女）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨昭恽家族的女子，姓名未载。951年家族遭陆孟俊杀害后，被送给马希崇；956年又被马转送韩令坤。陆孟俊被俘后，她请求复仇，称家中二百口被杀。保留称谓与本人说辞，不编造实名或将二百口当独立精确清点。", "biography": null, "status": "draft", "id": "edb92a40-ff47-5ffc-a704-86de9ba6accf"}, {"name": "马希崇", "aliases": ["馬希崇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希广的庶弟、马希萼的弟弟。947年任楚天策左司马，秘密致信马希萼指责继位安排，又向他报告马希广的言行并约为内应。生卒年尚未录入。", "biography": null, "status": "draft", "id": "7c876e99-eb52-5864-9569-0ede35f9ff7b"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "孟昶任李廷珪统左右卫圣诸军，分步骑为左右十军", "start_year": 956, "end_year": 956, "time_original": "956年三月甲寅", "dynasty": "五代十国", "description": "孟昶任李廷珪统左右卫圣诸军，分步骑为左右十军。", "phases": [], "location_name": "后蜀", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "9a7add90-30ee-5a1b-a27c-e32619ca4d36"}, {"title": "柴克宏任宣州巡检使时，驳斥不修城的理由，补齐城防器械", "start_year": null, "end_year": null, "time_original": "956年宣州战事以前的任巡检使旧事，具体任年未载", "dynasty": "五代十国", "description": "柴克宏初到宣州时，城堑失修、器械缺乏。当地官吏以田頵、王茂章、李遇先后叛乱后无人敢修为理由，柴认为时势已经改变，随后修缮完备。前人叛乱是官吏的解释，不在此重建956年三场叛乱。", "phases": [], "location_name": "宣州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "cc74350d-6160-530d-971b-67f38d604e69"}, {"title": "路彦铢攻宣州未克，闻吴程战败后撤兵", "start_year": 956, "end_year": 956, "time_original": "956年三月乙卯撤回，攻城起日未载", "dynasty": "五代十国", "description": "路彦铢攻宣州未克，闻吴程战败后撤兵。", "phases": [], "location_name": "宣州至吴越", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "57893252-3b8e-5b81-b270-b634d55aec29"}, {"title": "李璟任柴克宏为奉化节度使，柴再请领军救寿州", "start_year": 956, "end_year": 956, "time_original": "956年三月常宣战事之后，具体任命日未载", "dynasty": "五代十国", "description": "李璟任柴克宏为奉化节度使，柴再请领军救寿州。", "phases": [], "location_name": "南唐至寿州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b169d3c2-c4fb-5e6c-85a8-d21e2517b223"}