_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "8e541117-5a96-5558-8c13-c76c1dc41a67"}, {"title": "韩熙载认为亲王元帅已足可信，反对另设监军，李璟不听", "start_year": 956, "end_year": 956, "time_original": "956年南唐拒周部署时，具体上书日未载", "dynasty": "五代十国", "description": "韩熙载认为亲王元帅已足可信，反对另设监军，李璟不听。", "phases": [], "location_name": "南唐朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ca148dee-56ec-503a-8309-6deca6676e65"}, {"title": "李璟派潘承祐到泉建募兵，潘举荐许文稹等四人", "start_year": 956, "end_year": 956, "time_original": "956年三月南唐扩充兵力期间，具体日未载", "dynasty": "五代十国", "description": "李璟派潘承祐到泉建募兵，潘举荐许文稹等四人。", "phases": [], "location_name": "泉州、建州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b1c7a0c7-518d-502b-91a8-26f4208f9b4c"}, {"title": "李璟任许文稹为西面行营应援使，郑彦华、林仁肇为将", "start_year": 956, "end_year": 956, "time_original": "956年三月潘承祐举荐之后，具体日未载", "dynasty": "五代十国", "description": "李璟任许文稹为西面行营应援使，郑彦华、林仁肇为将。", "phases": [], "location_name": "南唐", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "0c4c8319-80bb-5908-acad-23033ab24b9f"}, {"title": "柴荣任李重进为庐寿招讨使、武行德为濠州城下都部署", "start_year": 956, "end_year": 956, "time_original": "956年四月甲子", "dynasty": "五代十国", "description": "柴荣任李重进为庐寿招讨使、武行德为濠州城下都部署。", "phases": [], "location_name": "庐寿及濠州战区", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "682532ed-8fb0-5818-9279-1fe6e769abc6"}, {"title": "陆孟俊率万余兵从常州赴泰州，周军退去，陆复城并派陈德诚守", "start_year": 956, "end_year": 956, "time_original": "956年四月淮南反攻时，具体日未载", "dynasty": "五代十国", "description": "陆孟俊率万