atus": "draft", "id": "54eea477-f28c-574a-83f5-0c3075d5fdf4"}, {"title": "韩令坤在扬州城东击败南唐军，俘陆孟俊", "start_year": 956, "end_year": 956, "time_original": "956年四月，《资治通鉴》未单列战日，《旧五代史》丁丑奏报", "dynasty": "五代十国", "description": "韩令坤在扬州城东击败南唐军，俘陆孟俊。", "phases": [], "location_name": "扬州城东", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e3a0e1d6-c821-54d3-b92d-1289267f885f"}, {"title": "《通鉴》追述陆孟俊参与废立时杀杨昭恽家族、夺财并献族女", "start_year": 951, "end_year": 951, "time_original": "951年楚国废马希萼、立马希崇之际的追述，具体日未载", "dynasty": "五代十国", "description": "《通鉴》追述陆孟俊参与废立时杀杨昭恽家族、夺财并献族女。", "phases": [], "location_name": "潭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "70c28886-fd4b-540d-9665-968cbcd44e55"}, {"title": "韩令坤入扬州后，马希崇把杨氏送给韩令坤，韩宠爱她", "start_year": 956, "end_year": 956, "time_original": "956年二月扬州入城之后的追述，具体日未载", "dynasty": "五代十国", "description": "韩令坤入扬州后，马希崇把杨氏送给韩令坤，韩宠爱她。", "phases": [], "location_name": "扬州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "87710bf6-52d2-59a1-9029-35f40e774a58"}, {"title": "陆孟俊被俘将送行在时，杨氏哭诉家仇，请韩令坤复仇", "start_year": 956, "end_year": 956, "time_original": "956年四月扬州俘陆以后", "dynasty": "五代十国", "description": "陆孟俊被俘将送行在时，杨氏哭诉家仇，请韩令坤复仇。", "phases": [], "location_name": "扬州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "eaf09e5b-1961-5798-ae8c-ced851dad32c"}, {"title": "韩令坤听取杨氏哭诉后杀死陆孟俊", "start_year": 956, "end_year": 956, "time_original": "956年四月扬州俘获后，具体处死日未载", "dynasty": "五代十国", "description": "韩令坤听取杨氏哭诉后杀死陆孟俊。", "phases": [], "location_name": "扬州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "daa76627-aa90-5f44-bce4-30970af29aae"}, {"title": "南唐齐王景达率二万兵渡江，在六合二十余里处筑栅不进", "start_year": 956, "end_year": 956, "time_original": "956年四月六合战前，具体渡江日未载", "dynasty": "五代十国", "description": "南唐齐王景达率二万兵渡江，在六合二十余里处筑栅不进。", "phases": [], "location_name": "瓜步济江至六合附近", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "817bfb78-3fb0-5637-af47-baa0f9e9269d"}, {"title": "赵匡胤因兵不满二千，主张等待南唐军出栅来攻", "start_year": 956, "end_year": 956, "time_original": "956年四月两军相对时", "dynasty": "五代十国", "description": "赵匡胤因兵不满二千，主张等待南唐军出栅来攻。", "phases": [], "location_name": "六合", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "979418f2-96a6-599c-900b-3e14d8a3f0df"}, {"title": "南唐军数日后来攻六合，赵匡胤反击获胜，败军渡江多人溺亡", "start_year": 956, "end_year": 956, "time_original": "956年四月设栅对峙数日后，具体战日未列", "dynasty": "五代十国", "description": "南唐兵数日后出栅攻六合，赵匡胤奋击取胜。《通鉴》记杀俘近五千，余众万余逃江争舟，多人溺亡，并以精卒尽作败势概述。旧史记斩首五千，《宋史》记斩首万余，杀俘与斩首口径不同且人数有差，不加总，也不推定南唐从此完全没有军队。", "phases": [], "location_name": "六合至渡江处", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b46b0253-8cbe-542c-a512-10a9960382e3"}]'::jsonb)
